class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        vector<int> res;
        res.reserve(queries.size());
        for (int q : queries) {
            int best = INT_MAX;
            for (auto& in : intervals)
                if (in[0] <= q && q <= in[1]) best = min(best, in[1] - in[0] + 1);
            res.push_back(best == INT_MAX ? -1 : best);
        }
        return res;
    }
};

