class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        sort(intervals.begin(), intervals.end());
        int n = queries.size();
        vector<int> idx(n), res(n, -1);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(),
             [&](int a, int b) { return queries[a] < queries[b]; });
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        int j = 0;
        for (int id : idx) {
            int q = queries[id];
            while (j < (int)intervals.size() && intervals[j][0] <= q) {
                pq.push({intervals[j][1] - intervals[j][0] + 1, intervals[j][1]});
                ++j;
            }
            while (!pq.empty() && pq.top().second < q) pq.pop();
            if (!pq.empty()) res[id] = pq.top().first;
        }
        return res;
    }
};

