var minInterval = function(intervals, queries) {
    intervals.sort((a, b) => a[0] - b[0]);
    const order = queries.map((q, i) => [q, i]).sort((a, b) => a[0] - b[0]);
    const res = new Array(queries.length).fill(-1);
    const heap = [];
    const push = (x) => {
        heap.push(x);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
                if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
                if (m === i) break;
                [heap[m], heap[i]] = [heap[i], heap[m]];
                i = m;
            }
        }
        return top;
    };
    let j = 0;
    for (const [q, qi] of order) {
        while (j < intervals.length && intervals[j][0] <= q) {
            push([intervals[j][1] - intervals[j][0] + 1, intervals[j][1]]);
            j++;
        }
        while (heap.length && heap[0][1] < q) pop();
        if (heap.length) res[qi] = heap[0][0];
    }
    return res;
};
